import{_ as i,H as a,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"32 | 技术解析：用户态eBPF与bpftime详解","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么需要用户态 eBPF？","slug":"为什么需要用户态-ebpf","link":"#为什么需要用户态-ebpf","children":[]},{"level":2,"title":"bpftime 核心原理","slug":"bpftime-核心原理","link":"#bpftime-核心原理","children":[{"level":3,"title":"核心技术一：二进制重写","slug":"核心技术一-二进制重写","link":"#核心技术一-二进制重写","children":[]},{"level":3,"title":"核心技术二：用户态 BPF 虚拟机","slug":"核心技术二-用户态-bpf-虚拟机","link":"#核心技术二-用户态-bpf-虚拟机","children":[]},{"level":3,"title":"核心技术三：共享内存 Maps","slug":"核心技术三-共享内存-maps","link":"#核心技术三-共享内存-maps","children":[]},{"level":3,"title":"兼容性设计","slug":"兼容性设计","link":"#兼容性设计","children":[]}]},{"level":2,"title":"与内核 eBPF 的对比与选择","slug":"与内核-ebpf-的对比与选择","link":"#与内核-ebpf-的对比与选择","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"eBPF核心技术与实战/32｜技术解析：用户态eBPF与bpftime详解.md","filePath":"eBPF核心技术与实战/32｜技术解析：用户态eBPF与bpftime详解.md","lastUpdated":1795536221000}'),t={name:"eBPF核心技术与实战/32｜技术解析：用户态eBPF与bpftime详解.md"};function n(l,s,h,r,o,k){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_32-技术解析-用户态ebpf与bpftime详解" tabindex="-1">32 | 技术解析：用户态eBPF与bpftime详解 <a class="header-anchor" href="#_32-技术解析-用户态ebpf与bpftime详解" aria-label="Permalink to &quot;32 | 技术解析：用户态eBPF与bpftime详解&quot;">​</a></h1><p>你好，我是倪朋飞。</p><p>在上一讲中，我带你一起探讨了如何使用 eBPF 来诊断 GPU 工作负载的性能问题。通过追踪CUDA 运行时和驱动层的关键函数，我们可以深入了解大模型训练和推理过程中的性能瓶颈。不过，你可能也注意到了，当我们使用 uprobe 跟踪用户态函数时，总会面临一个令人头疼的问题，也就是性能开销。</p><p>还记得 09 讲中讨论过的用户态跟踪内容吗？我特别提醒过你，uprobe 本质上是通过断点去执行处理程序，跟踪高频函数会带来显著的性能开销。那么，有没有办法既享受 eBPF 的强大功能，又能大幅降低用户态跟踪的性能开销呢？</p><p>今天，我就来带你了解旨在解决这个问题的用户态 eBPF 运行时。我们将以 bpftime 项目为核心，深入解析它的原理、应用场景和未来发展方向。</p><h2 id="为什么需要用户态-ebpf" tabindex="-1">为什么需要用户态 eBPF？ <a class="header-anchor" href="#为什么需要用户态-ebpf" aria-label="Permalink to &quot;为什么需要用户态 eBPF？&quot;">​</a></h2><p>在深入技术细节之前，我们先来理解一个问题：为什么要在用户态运行 eBPF 程序？</p><p>要理解用户态 eBPF 的价值，我们先来看看内核 uprobe 的工作原理。</p><p>当你使用 uprobe 跟踪一个用户态函数时，内核的处理流程是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户态函数调用 → int3 中断 → 陷入内核态 → 执行 BPF 程序 → 返回用户态</span></span></code></pre></div><p>这个过程涉及两次特权级切换——先从用户态陷入内核态，再从内核态返回用户态。每次特权级切换都意味着 CPU 寄存器的保存和恢复、可能的页表切换、缓存污染以及安全检查开销。</p><p>那么，如果把 eBPF 虚拟机搬到用户态运行，情况会怎样？整个执行流程变成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户态函数调用 → 跳转到 BPF 程序 → 执行 BPF 程序 → 返回原函数</span></span></code></pre></div><p>整个过程完全在用户态完成，没有特权级切换。这就是用户态 eBPF 的核心思想。</p><p>下图直观展示了两种方案的执行流程差异：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/eBPF%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/32/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/eBPF%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/32/1.png" alt=""></a></p><p>从图中可以看到，内核 uprobe 每次调用约需 2500ns，而用户态 eBPF 只需约 190ns，性能提升超过 13 倍。这个差距在跟踪高频函数时会被急剧放大，这也是为什么在生产环境中，很多团队不敢开启持续的用户态追踪。他们只能在问题发生时临时开启，但往往也意味着错过了最关键的诊断窗口。</p><p>除了性能优势，用户态 eBPF 还带来了其他好处：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>降低内核侧权限依赖：内核 eBPF 需要 CAP_BPF（或更早版本的 CAP_SYS_ADMIN）以及</span></span>
<span class="line"><span>CAP_PERFMON 等权限，还受 perf_event_paranoid 等系统策略限制。用户态 eBPF</span></span>
<span class="line"><span>不走内核 BPF 子系统，但如果需要注入到其他进程，仍然需要 ptrace 权限（受同一</span></span>
<span class="line"><span>UID、kernel.yama.ptrace_scope 等限制）。</span></span></code></pre></div><ol start="2"><li><p>更小的安全攻击面：不在内核中运行，即使出现问题也不会影响整个系统。</p></li><li><p>更灵活的部署：可以在没有 eBPF 支持的老内核或受限容器中使用。</p></li><li><p>功能扩展：可以实现内核 uprobe 不支持的功能，如修改函数返回值。</p></li></ol><h2 id="bpftime-核心原理" tabindex="-1">bpftime 核心原理 <a class="header-anchor" href="#bpftime-核心原理" aria-label="Permalink to &quot;bpftime 核心原理&quot;">​</a></h2><p>了解了用户态 eBPF 的必要性之后，接下来我们一起看看 bpftime 是如何实现这一目标的。</p><p>bpftime 是一个开源的用户态 eBPF 运行时，由 eunomia-bpf 社区开发。bpftime 的设计目标是：在不修改任何代码的情况下，让现有的 eBPF 工具和应用程序在用户态运行，同时保持与内核 eBPF 的完全兼容。</p><p>需要注意的是，bpftime 目前仍处于早期开发阶段，API 可能会有变动，官方文档也提醒不建议直接用于生产环境。如果你打算在正式项目中使用，建议先在测试环境充分验证，并关注项目的版本更新。</p><p>bpftime 的整体设计可以用一句话概括：用二进制重写劫持函数入口，用用户态虚拟机执行BPF 代码，用共享内存实现数据通信。</p><p>如下图所示，就是 bpftime 的架构示意图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/eBPF%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/32/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/eBPF%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/32/2.png" alt=""></a></p><p>从架构图可以看到，当目标程序的函数被调用时，控制流首先被二进制重写引擎劫持到跳板代码，然后由用户态 BPF 虚拟机执行 eBPF 字节码，执行过程中产生的数据通过共享内存Maps 与控制平面通信。整个过程都在用户态完成，不需要陷入内核。</p><p>接下来，我们逐一看看这三项核心技术是如何实现的。</p><h3 id="核心技术一-二进制重写" tabindex="-1">核心技术一：二进制重写 <a class="header-anchor" href="#核心技术一-二进制重写" aria-label="Permalink to &quot;核心技术一：二进制重写&quot;">​</a></h3><p>二进制重写（Binary Rewriting）是 bpftime 实现动态跟踪的关键技术。它的基本思想是：在运行时修改目标函数的机器码，将控制流重定向到我们的跳板代码。</p><p>bpftime 的二进制重写实现受到了两个开源项目的启发：</p><ul><li><p>frida-gum：著名的动态插桩框架，提供了用户态函数 hook 的能力。</p></li><li><p>zpoline：USENIX ATC’23 发表的系统调用拦截技术。</p></li></ul><p>具体来说，当你想跟踪一个用户态函数时，bpftime 会执行以下步骤：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">//</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 原始函数入口（假设）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target_function:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   mov</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbp,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsp</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">//</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 重写后的函数入口</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target_function:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   jmp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trampoline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     ; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">跳转到跳板代码</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   nop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">                ; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">填充对齐</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">trampoline:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   ; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">保存寄存器状态</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   ; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">调用</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BPF</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 程序</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   ; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">恢复寄存器状态</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   ; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">跳回原函数继续执行（如果需要）</span></span></code></pre></div><p>这种方法的优点是：</p><ul><li><p>零拷贝：直接在原地修改代码，不需要创建函数副本。</p></li><li><p>低延迟：只需要一次跳转指令，开销极小。</p></li><li><p>透明性：对被跟踪程序完全透明，无需重编译。</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bpftime 还支持通过 ptrace 机制将运行时注入到已经运行的进程中，这意味着你可以在不重</span></span></code></pre></div><p>启进程的情况下开始跟踪。</p><h3 id="核心技术二-用户态-bpf-虚拟机" tabindex="-1">核心技术二：用户态 BPF 虚拟机 <a class="header-anchor" href="#核心技术二-用户态-bpf-虚拟机" aria-label="Permalink to &quot;核心技术二：用户态 BPF 虚拟机&quot;">​</a></h3><p>bpftime 实现了一个完整的用户态 BPF 虚拟机，用于执行 eBPF 字节码。这个虚拟机有三种执行模式：</p><ul><li><p>LLVM JIT 编译器：LLVM 即时编译器（Just-In-Time Compiler，简称 JIT）将 eBPF 字节码即时编译为本地机器码。这是性能最高的执行模式，编译后的代码几乎与手写的 C 代码一样高效。LLVM JIT 还提供了跨平台支持，包括 x86_64、ARM64 和 RISC-V 架构。</p></li><li><p>ubpf JIT 编译器：基于 ubpf 项目的轻量级 JIT 编译器。相比 LLVM JIT，它的编译开销更小、启动更快，但生成的代码性能略低。适合对启动时间敏感的场景。</p></li><li><p>ubpf 解释器：对于某些不需要极致性能的场景，bpftime 也提供了基于 ubpf 的解释器模式。虽然执行速度较慢，但启动最快，内存占用最小，适合调试或资源受限的环境。</p></li></ul><h3 id="核心技术三-共享内存-maps" tabindex="-1">核心技术三：共享内存 Maps <a class="header-anchor" href="#核心技术三-共享内存-maps" aria-label="Permalink to &quot;核心技术三：共享内存 Maps&quot;">​</a></h3><p>在内核 eBPF 中，BPF Maps 是用户态程序和内核态 BPF 程序之间共享数据的桥梁。bpftime在用户态实现了类似的机制，但使用的是共享内存而不是内核数据结构。</p><p>这种设计的优势在于：</p><ol><li><p>进程间共享：多个进程可以同时访问同一个 Map，实现分布式数据收集。</p></li><li><p>与控制平面通信：跟踪数据可以实时传递给分析工具。</p></li><li><p>语义一致性：与内核 BPF Maps 的 API 完全兼容。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bpftime 还支持 ring buffer 和 perf buffer，用于高效地将事件数据从 BPF 程序传递</span></span></code></pre></div><p>到用户态分析程序。</p><h3 id="兼容性设计" tabindex="-1">兼容性设计 <a class="header-anchor" href="#兼容性设计" aria-label="Permalink to &quot;兼容性设计&quot;">​</a></h3><p>了解了 bpftime 的三项核心技术之后，你可能会问：它与现有的 eBPF 生态能否无缝对接？接下来我们就来看看 bpftime 的兼容性设计。</p><p>bpftime 的一个重要设计目标是与现有 eBPF 生态系统完全兼容。这意味着：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你可以直接使用 clang 编译 BPF 程序，无需任何修改</span></span></code></pre></div><ul><li><p>现有的 libbpf 程序可以直接在 bpftime 上运行</p></li><li><p>bpftrace 脚本可以无缝迁移到用户态执行</p></li><li><p>BCC 工具也可以在用户态运行</p></li></ul><p>例如，下面是使用 bpftime 运行 bpftrace 脚本的一个完整示例：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 传统的内核态 bpftrace（需要 root 权限）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bpftrace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;uretprobe:/usr/bin/bash:readline { printf(&quot;cmd: %s\\n&quot;, str(retv</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"># 使用 bpftime 在用户态运行（通常不需要root，但bpftrace的支持暂时还需要以root用户来运行）</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"># 先把 bpftrace 脚本加载到 bpftime 的共享内存中</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bpftime load bpftrace -e &#39;uretprobe:/usr/bin/bash:readline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;cmd: %s\\n&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 再用 bpftime 启动一个 bash，让 bpftime agent 注入到该进程</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bpftime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/bin/bash</span></span></code></pre></div><p>两种方式使用的是完全相同的 bpftrace 脚本。差别在于：内核态 bpftrace 需要把探针挂到内核里，通常需要 root；bpftime 走用户态注入链路，在同一用户启动的进程中往往不需要</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root，但如果你要 attach 到已运行的进程，通常需要 CAP_SYS_PTRACE 或 sudo。</span></span></code></pre></div><h2 id="与内核-ebpf-的对比与选择" tabindex="-1">与内核 eBPF 的对比与选择 <a class="header-anchor" href="#与内核-ebpf-的对比与选择" aria-label="Permalink to &quot;与内核 eBPF 的对比与选择&quot;">​</a></h2><p>了解了用户态 eBPF 的能力之后，你可能会问：是否意味着我们应该放弃内核 eBPF 呢？当然不是。用户态 eBPF 和内核 eBPF 是互补关系，各有各的适用场景。接下来，我就带你一起来看看在实际工作中应该如何选择。</p><p>下图是一个快速决策指南，帮助你根据追踪需求选择合适的方案：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/eBPF%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/32/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/eBPF%E6%A0%B8%E5%BF%83%E6%8A%80%E6%9C%AF%E4%B8%8E%E5%AE%9E%E6%88%98/images/32/3.png" alt=""></a></p><p>从图中可以看到，选择的核心依据是你要追踪的目标在内核态还是用户态。如果你需要追踪内核函数、网络协议栈、文件系统等内核行为，那内核 eBPF 是唯一的选择，这一点没有争议。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>而如果你的目标是用户态函数，那就需要进一步考虑函数的调用频率了：对于 malloc、SSL</span></span></code></pre></div><p>函数、语言运行时等高频调用的函数，bpftime 带来的性能优势是非常明显的。</p><p>除了单独使用，bpftime 还可以与内核 eBPF 协同工作。比如，你可以用 bpftime 在用户态收集应用层的调用信息，同时用内核 kprobe 追踪系统调用和网络栈，最后把两边的数据关联起来分析。这种混合方案可以实现端到端的可观测性，是很多复杂排障场景的最佳选择。</p><p>当然，在实际使用 bpftime 之前，你还需要了解它的一些限制和潜在风险。</p><ul><li><p>首先是功能边界的问题。bpftime 覆盖的是用户态观测和注入能力，无法替代 kprobe、tracepoint 等内核追踪手段，自然也看不到内核数据结构。</p></li><li><p>其次是二进制重写带来的风险。修改正在运行的进程内存，如果跳板代码有 bug 可能导致目标进程崩溃；某些编译器优化（如函数内联、尾调用优化）可能导致 hook 失效；如果目</p></li><li><p>标程序同时被其他 hook 工具（如 Frida、LD_PRELOAD）修改，也可能产生冲突。</p></li><li><p>最后是权限和安全策略的限制。注入其他进程需要 ptrace 权限，在容器环境或启用了</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ptrace_scope=2 的系统上可能被拒绝；某些安全软件也会检测和阻止进程注入行为。</span></span></code></pre></div><p>综合来看，如果你的场景是追踪内核函数或网络协议栈内部行为，或者目标程序运行在无法获取 ptrace 权限的环境（如某些 PaaS 平台），那 bpftime 就不太适用了。对于稳定性要求极高的生产环境核心服务，我也建议你先在测试环境充分验证之后再考虑上线</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天，我带你一起了解了用户态 eBPF 技术的原理和应用。</p><p>内核 uprobe 的性能瓶颈源于用户态到内核态的特权级切换，这在高频函数追踪场景下会带来显著的性能损失。而 bpftime 通过二进制重写、用户态 BPF 虚拟机和共享内存 Maps 这三项核心技术，实现了完全在用户态运行 eBPF 程序的能力。</p><p>从性能测试数据来看，bpftime 的 uprobe 性能比内核版本快了一个数量级，这意味着我们终于可以在生产环境中持续开启用户态追踪，而不用担心对业务造成严重影响。</p><p>需要注意的是，用户态 eBPF 与内核 eBPF 是互补关而不是替代关系。内核 eBPF 仍然是内核级追踪的首选方案，而用户态 eBPF 则更适合高频用户态函数追踪的场景。两者可以协同工作，提供端到端的可观测性。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在课程结束之前，我想邀请你来聊一聊：bpftime 使用二进制重写技术修改函数入口点，你能想到这种方法可能带来哪些潜在风险吗？如何在安全性和灵活性之间取得平衡？</p><p>欢迎在留言区和我讨论，也欢迎把这节课分享给你的同事、朋友。让我们一起在实战中演练，在交流中进步。</p>`,77)])])}const c=i(t,[["render",n]]);export{b as __pageData,c as default};
